// Embeds src/annotate.html into src/annotate_html.ts (a plain string export),
// so the Worker bundle and the vitest runtime need no special loaders.
import { readFileSync, writeFileSync } from "node:fs";
const dir = new URL("../src/", import.meta.url);
const html = readFileSync(new URL("annotate.html", dir), "utf8");
const out =
  "// GENERATED by scripts/build-html.mjs from src/annotate.html. Edit the .html, then `npm run build:html`.\n" +
  `export const ANNOTATE_HTML: string = ${JSON.stringify(html)};\n`;
writeFileSync(new URL("annotate_html.ts", dir), out);
console.log(`annotate_html.ts: ${html.length} chars`);
